using System;
using System.IO;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using System.Linq;
using System.Collections.Generic;

void InspectAssembly\(string path, string[] typeNamesToFind\)
{
    using var stream = File.OpenRead\(path\);
    using var peReader = new PEReader\(stream\);
    var mdReader = peReader.GetMetadataReader\(\);

    // Build a mapping of type handles to names
    var typeMap = new Dictionary<TypeDefinitionHandle, string>\(\);
    var typeRefMap = new Dictionary<TypeReferenceHandle, string>\(\);

    foreach \(var typeDefHandle in mdReader.TypeDefinitions\)
    {
        var typeDef = mdReader.GetTypeDefinition\(typeDefHandle\);
        var ns = mdReader.GetString\(typeDef.Namespace\);
        var name = mdReader.GetString\(typeDef.Name\);
        var fullName = string.IsNullOrEmpty\(ns\) ? name : $"{ns}.{name}";
        typeMap[typeDefHandle] = fullName;
    }

    foreach \(var typeRefHandle in mdReader.TypeReferences\)
    {
        var typeRef = mdReader.GetTypeReference\(typeRefHandle\);
        var ns = mdReader.GetString\(typeRef.Namespace\);
        var name = mdReader.GetString\(typeRef.Name\);
        var fullName = string.IsNullOrEmpty\(ns\) ? name : $"{ns}.{name}";
        typeRefMap[typeRefHandle] = fullName;
    }

    string ResolveName\(EntityHandle handle\)
    {
        if \(handle.Kind == HandleKind.TypeDefinition\)
            return typeMap.GetValueOrDefault\(\(TypeDefinitionHandle\)handle, "?"\);
        if \(handle.Kind == HandleKind.TypeReference\)
            return typeRefMap.GetValueOrDefault\(\(TypeReferenceHandle\)handle, "?"\);
        return "?";
    }

    // Find events for specified types
    foreach \(var typeDefHandle in mdReader.TypeDefinitions\)
    {
        var typeDef = mdReader.GetTypeDefinition\(typeDefHandle\);
        var typeName = mdReader.GetString\(typeDef.Name\);
        var typeNs = mdReader.GetString\(typeDef.Namespace\);
        var fullTypeName = string.IsNullOrEmpty\(typeNs\) ? typeName : $"{typeNs}.{typeName}";

        bool isEventArgs = typeNamesToFind.Any\(n => typeName.Contains\(n, StringComparison.OrdinalIgnoreCase\)\);

        if \(isEventArgs\)
        {
            Console.WriteLine\($"\\n=== {fullTypeName} ==="\);

            // Show base type
            if \(!typeDef.BaseType.IsNil\)
                Console.WriteLine\($"  Base: {ResolveName\(typeDef.BaseType\)}"\);

            // Show properties
            foreach \(var propHandle in typeDef.GetProperties\(\)\)
            {
                var prop = mdReader.GetPropertyDefinition\(propHandle\);
                var propName = mdReader.GetString\(prop.Name\);

                // Get property signature
                var sig = mdReader.GetBlobReader\(prop.Signature\);
                Console.WriteLine\($"  Property: {propName}"\);
            }

            // Show events
            foreach \(var evtHandle in typeDef.GetEvents\(\)\)
            {
                var evt = mdReader.GetEventDefinition\(evtHandle\);
                var evtName = mdReader.GetString\(evt.Name\);
                var evtType = ResolveName\(evt.Type\);
                Console.WriteLine\($"  Event: {evtName} -> {evtType}"\);
            }
        }
    }
}

