using System;
using System.IO;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using System.Linq;
using System.Collections.Generic;
using System.Collections.Immutable;

string ResolveTypeName\(MetadataReader mdReader, EntityHandle handle\)
{
    switch \(handle.Kind\)
    {
        case HandleKind.TypeDefinition:
            var td = mdReader.GetTypeDefinition\(\(TypeDefinitionHandle\)handle\);
            var tdNs = mdReader.GetString\(td.Namespace\);
            var tdName = mdReader.GetString\(td.Name\);
            return string.IsNullOrEmpty\(tdNs\) ? tdName : $"{tdNs}.{tdName}";
        case HandleKind.TypeReference:
            var tr = mdReader.GetTypeReference\(\(TypeReferenceHandle\)handle\);
            var trNs = mdReader.GetString\(tr.Namespace\);
            var trName = mdReader.GetString\(tr.Name\);
            return string.IsNullOrEmpty\(trNs\) ? trName : $"{trNs}.{trName}";
        case HandleKind.TypeSpecification:
            var ts = mdReader.GetTypeSpecification\(\(TypeSpecificationHandle\)handle\);
            var blob = mdReader.GetBlobReader\(ts.Signature\);
            return DecodeTypeSpec\(mdReader, ref blob\);
        default:
            return $"[{handle.Kind}]";
    }
}

string DecodeTypeSpec\(MetadataReader mdReader, ref BlobReader blob\)
{
    var sigType = blob.ReadByte\(\);
    switch \(sigType\)
    {
        case 0x15: // ELEMENT_TYPE_GENERICINST
            var genKind = blob.ReadByte\(\); // class or valuetype
            var genTypeHandle = blob.ReadTypeHandle\(\);
            var genTypeName = ResolveTypeName\(mdReader, genTypeHandle\);
            var argCount = blob.ReadCompressedInteger\(\);
            var args = new List<string>\(\);
            for \(int i = 0; i < argCount; i++\)
            {
                args.Add\(DecodeTypeSpec\(mdReader, ref blob\)\);
            }
            return $"{genTypeName}<{string.Join\(", ", args\)}>";
        case 0x12: // ELEMENT_TYPE_CLASS
        case 0x11: // ELEMENT_TYPE_VALUETYPE
            var classHandle = blob.ReadTypeHandle\(\);
            return ResolveTypeName\(mdReader, classHandle\);
        case 0x01: return "void";
        case 0x02: return "bool";
        case 0x08: return "int";
        case 0x0E: return "string";
        case 0x1C: return "object";
        default:
            return $"[sig:0x{sigType:X2}]";
    }
}

void InspectEvents\(string path, string typeName\)
{
    using var stream = File.OpenRead\(path\);
    using var peReader = new PEReader\(stream\);
    var mdReader = peReader.GetMetadataReader\(\);

    foreach \(var typeDefHandle in mdReader.TypeDefinitions\)
    {
        var typeDef = mdReader.GetTypeDefinition\(typeDefHandle\);
        var name = mdReader.GetString\(typeDef.Name\);
        var ns = mdReader.GetString\(typeDef.Namespace\);
        var fullName = string.IsNullOrEmpty\(ns\) ? name : $"{ns}.{name}";

        if \(name != typeName\) continue;

        Console.WriteLine\($"\\n=== {fullName} Events ==="\);
        foreach \(var evtHandle in typeDef.GetEvents\(\)\)
        {
            var evt = mdReader.GetEventDefinition\(evtHandle\);
            var evtName = mdReader.GetString\(evt.Name\);
            var evtTypeName = ResolveTypeName\(mdReader, evt.Type\);
            Console.WriteLine\($"  {evtName}: {evtTypeName}"\);
        }
    }
}

